values.flexJson:
={
  "type": "bubble",
  "header": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "text",
        "text": "RefCare 轉介平台",
        "color": "#ffffff",
        "size": "xs",
        "weight": "bold"
      },
      {
        "type": "text",
        "text": "{{ $('Webhook-全區機構').item.json.body.notify_type === 'update' ? '個案需求變更通知' : '新個案派發通知' }}",
        "color": "#ffffff",
        "size": "xl",
        "weight": "bold",
        "margin": "xs"
      }
    ],
    "background": {
      "type": "linearGradient",
      "angle": "135deg",
      "startColor": "{{ $('Webhook-全區機構').item.json.body.notify_type === 'update' ? '#f59e0b' : '#0f766e' }}",
      "endColor": "{{ $('Webhook-全區機構').item.json.body.notify_type === 'update' ? '#d97706' : '#115e59' }}"
    },
    "paddingAll": "20px"
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "box",
        "layout": "horizontal",
        "contents": [
          {
            "type": "text",
            "text": "案件編號",
            "color": "#64748b",
            "size": "sm",
            "flex": 2
          },
          {
            "type": "text",
            "text": "{{ $('Webhook-全區機構').item.json.body.case_id }}",
            "color": "#0f766e",
            "size": "sm",
            "weight": "bold",
            "flex": 5
          }
        ]
      },
      {
        "type": "box",
        "layout": "horizontal",
        "contents": [
          {
            "type": "text",
            "text": "轉介醫院",
            "color": "#64748b",
            "size": "sm",
            "flex": 2
          },
          {
            "type": "text",
            "text": "{{ $('Webhook-全區機構').item.json.body.hospital }}",
            "color": "#1e293b",
            "size": "sm",
            "weight": "bold",
            "flex": 5
          }
        ],
        "margin": "md"
      },
      {
        "type": "separator",
        "margin": "lg",
        "color": "#f1f5f9"
      },
      {
        "type": "box",
        "layout": "vertical",
        "contents": [
          {
            "type": "box",
            "layout": "horizontal",
            "contents": [
              {
                "type": "text",
                "text": "👤 案主背景",
                "color": "#475569",
                "size": "sm",
                "flex": 3
              },
              {
                "type": "text",
                "text": "{{ ($('Webhook-全區機構').item.json.body.patient_name || '無')[0] }}◯{{ $('Webhook-全區機構').item.json.body.gender === '男' ? '先生' : '女士' }} ({{ $('Webhook-全區機構').item.json.body.age }}歲)",
                "color": "#0f172a",
                "size": "sm",
                "weight": "bold",
                "flex": 4
              }
            ]
          },
          {
            "type": "box",
            "layout": "horizontal",
            "contents": [
              {
                "type": "text",
                "text": "♿ 失能等級",
                "color": "#475569",
                "size": "sm",
                "flex": 3
              },
              {
                "type": "text",
                "text": "{{ $('Webhook-全區機構').item.json.body.cms_level || '未評估' }}",
                "color": "#e11d48",
                "size": "sm",
                "weight": "bold",
                "flex": 4
              }
            ],
            "margin": "sm"
          },
          {
            "type": "box",
            "layout": "horizontal",
            "contents": [
              {
                "type": "text",
                "text": "💡 轉介項目",
                "color": "#475569",
                "size": "sm",
                "flex": 3
              },
              {
                "type": "text",
                "text": "{{ $('Webhook-全區機構').item.json.body.service_type }}",
                "color": "#0f172a",
                "size": "sm",
                "weight": "bold",
                "flex": 4
              }
            ],
            "margin": "sm"
          },
          {
            "type": "box",
            "layout": "horizontal",
            "contents": [
              {
                "type": "text",
                "text": "🛠️ 服務代碼",
                "color": "#475569",
                "size": "sm",
                "flex": 3
              },
              {
                "type": "text",
                "text": "{{ ($('Webhook-全區機構').item.json.body.service_codes || []).join(', ') || '無' }}",
                "color": "#0f172a",
                "size": "sm",
                "weight": "bold",
                "flex": 4
              }
            ],
            "margin": "sm"
          }
        ],
        "margin": "lg"
      }
    ],
    "paddingAll": "20px"
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "contents": [
      {
        "type": "button",
        "action": {
          "type": "uri",
          "label": "⚡ 立即前往媒合回覆",
          "uri": "https://refcare.zeabur.app/facility.html?case_id={{ $('Webhook-全區機構').item.json.body.case_id }}"
        },
        "style": "primary",
        "color": "{{ $('Webhook-全區機構').item.json.body.notify_type === 'update' ? '#d97706' : '#0f766e' }}",
        "height": "sm"
      },
      {
        "type": "button",
        "action": {
          "type": "uri",
          "label": "📋 複製完整個案訊息",
          "uri": "https://refcare.zeabur.app/facility.html?case_id={{ $('Webhook-全區機構').item.json.body.case_id }}&auto_copy=1"
        },
        "style": "secondary",
        "margin": "sm",
        "height": "sm"
      }
    ],
    "paddingAll": "16px"
  }
}
